# -*- coding: utf-8 -*-
"""Word 結案報告生成模組
依照 Word 範本填入 PDF 自動抓到的資料 + 使用者手動補填的欄位
"""
import base64
import io
import re
from copy import deepcopy
from datetime import date, datetime, timedelta
from typing import Optional

from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml.ns import qn
from docx.oxml import OxmlElement
from openpyxl.utils import get_column_letter  # 不會用到,只是確保依賴

# ==================== Word 範本(base64 編碼)====================
WORD_TEMPLATE_B64 = """"""


def _get_template_bytes() -> bytes:
    """取得 Word 範本的二進位資料"""
    return base64.b64decode(WORD_TEMPLATE_B64)



# ==================== 工具函式 ====================

def _replace_paragraph_text(paragraph, new_text: str):
    """替換段落文字,保留第一個 run 的格式(字型、顏色、大小)
    其他 run 會被移除
    """
    if not paragraph.runs:
        paragraph.text = new_text
        return
    # 保留第一個 run,改其文字
    first_run = paragraph.runs[0]
    first_run.text = new_text
    # 移除其他 run
    for run in paragraph.runs[1:]:
        run._r.getparent().remove(run._r)


def _insert_paragraph_after(paragraph, text: str = "", style=None):
    """在指定段落後面插入一個新段落,複製原段落的樣式
    回傳新段落的 _p 元素(docx Paragraph)
    """
    new_p = deepcopy(paragraph._p)
    # 清空內容,保留段落屬性(樣式)
    for child in list(new_p):
        if child.tag == qn('w:r'):
            new_p.remove(child)
    paragraph._p.addnext(new_p)
    # 用 python-docx 的 Paragraph 包起來
    from docx.text.paragraph import Paragraph
    new_para = Paragraph(new_p, paragraph._parent)
    if text:
        _replace_paragraph_text_or_add(new_para, text)
    return new_para


def _replace_paragraph_text_or_add(paragraph, text: str):
    """替換段落文字(保留格式),若無 run 則新增一個"""
    if paragraph.runs:
        first_run = paragraph.runs[0]
        first_run.text = text
        for run in paragraph.runs[1:]:
            run._r.getparent().remove(run._r)
    else:
        paragraph.add_run(text)


def _remove_paragraph(paragraph):
    """從文件中移除指定段落"""
    p = paragraph._p
    p.getparent().remove(p)


def _set_cell_text(cell, text: str, bold: bool = False):
    """設定表格儲存格文字,保留原格式(複製第一個 run 樣式)"""
    # 清空原本的段落內容
    for para in cell.paragraphs:
        if para.runs:
            # 保留第一個 run 的格式,改文字
            first_run = para.runs[0]
            first_run.text = text
            if bold:
                first_run.bold = True
            # 移除多餘 run
            for run in para.runs[1:]:
                run._r.getparent().remove(run._r)
            # 只需要一段,移除其他段落
            for extra in cell.paragraphs[1:]:
                _remove_paragraph(extra)
            return
    # 若 cell 沒 run,直接 add
    cell.text = text


# ==================== 主生成函式 ====================

def build_word_report(data: dict) -> bytes:
    """生成 Word 結案報告
    
    data 結構:
    {
        # === 基本資訊 ===
        "操作走期_開始": "2026/06/01",
        "操作走期_結束": "2026/08/10",
        "工作天數": 50,
        "操作目的_行": ["a.XXX", "b.XXX"],  # 可多行
        "執行篇數細項": "4-5圖心得文 X 篇、...",  # PDF 自動產
        "預計執行篇數": 89,
        "實際執行篇數": 89,
        "達成率": "100%",
        
        # === 保證效益表(KPI) ===
        "KPI": [  # 從 Excel 邏輯來
            {"項目": "網友回應數", "說明": "開題與置入真實回應(原保證52篇)", "達成": "118篇"},
            ...
        ],
        
        # === 網路聲量 ===
        "聲量_自品名稱": "AAA自品",
        "聲量_自品成長數": 15,
        "聲量_自品成長率": "25.00%",
        "聲量_自品集中版面": "Threads、Dcard",
        "聲量_競品A名稱": "BBB競品",
        "聲量_競品A成長數": 10,
        "聲量_競品A成長率": "12.50%",
        "聲量_競品A集中版面": "Threads",
        "聲量_競品B名稱": "CCC競品",
        "聲量_競品B成長數": 5,
        "聲量_競品B成長率": "8.00%",
        "聲量_競品B集中版面": "Threads",
        "聲量_觀察區間_前": "2026/3/1~2026/5/31",
        "聲量_觀察區間_後": "2026/3/1~2026/8/10",
        
        # === 自品文字雲與正負評 ===
        "自品_文字雲_bytes": None,  # 圖片 bytes 或 None
        "自品_文字雲_分析": "本區間XXXXXX",
        "自品_正評": ["正評 1", "正評 2", ...],  # 任意行數
        "自品_負評": ["負評 1", ...],
        "自品_整體分析": "整體以XXXXX",
        
        # === 競品文字雲與正負評 ===
        "競品_文字雲_bytes": None,
        "競品_文字雲_分析": "...",
        "競品_正評": [...],
        "競品_負評": [...],
        "競品_整體分析": "...",
        
        # === 專案回應評價分佈 ===
        "實際溝通量": 89,
        "保證網友回應數": 52,
        "實際回應數": 413,
        "分布表": [  # 從 Excel 邏輯來
            {"版面": "PTT", "實際溝通": 52, "正面": 0, "負面": 0, "議題": 295, "產品": 0, "複合": 0, "小計": 295},
            ...
        ],
        
        # === 專案正負評摘要 ===
        "專案_正評": [...],  # 任意行數
        "專案_負評": [...],
        
        # === 操作觀察與未來建議 ===
        "操作觀察": ["觀察 1", "觀察 2", ...],
        "未來建議": ["建議 1", ...],
        
        # === 平台熱門效益(選填)===
        "有_Threads破萬": False,
        "Threads_瀏覽次數": 10,  # 萬
        "Threads_愛心": 500,
        "Threads_留言": 50,
        "Threads_截圖_bytes": None,
        "有_Dcard熱門": False,
        "Dcard_板名排名": "美妝版熱門前5",
        "Dcard_愛心": 300,
        "Dcard_留言": 80,
        "Dcard_曝光": "5萬次",
        "Dcard_截圖_bytes": None,
    }
    
    回傳 Word .docx 的 bytes
    """
    doc = Document(io.BytesIO(_get_template_bytes()))
    
    paras = doc.paragraphs
    tables = doc.tables
    
    # ===== 段落替換 =====
    # [1] 操作走期
    走期 = f"操作走期:{data['操作走期_開始']}~{data['操作走期_結束']}(共{data['工作天數']}個工作天)"
    _replace_paragraph_text(paras[1], 走期)
    
    # [3] [4] 操作目的 — 可能多於 2 行,動態插入
    # 原範本 paras[3]="a.XXXXX" paras[4]="b. XXXXX" 兩行
    # 處理:先替換前 2 行,如有更多就插入在後面
    目的_行 = data.get('操作目的_行', [])
    目的_行 = [l for l in 目的_行 if l.strip()]  # 去空行
    if len(目的_行) >= 1:
        _replace_paragraph_text(paras[3], 目的_行[0])
    else:
        _replace_paragraph_text(paras[3], "")
    if len(目的_行) >= 2:
        _replace_paragraph_text(paras[4], 目的_行[1])
    else:
        _replace_paragraph_text(paras[4], "")
    # 若還有第 3 行以上,在 paras[4] 後插入
    for extra in 目的_行[2:]:
        _insert_paragraph_after(paras[4], extra)
    
    # [5] 預計/實際/達成率
    _replace_paragraph_text(
        paras[5],
        f"預計執行{data['預計執行篇數']}篇、實際執行{data['實際執行篇數']}篇、達成率{data['達成率']}"
    )
    
    # [6] 執行篇數細項
    _replace_paragraph_text(paras[6], f"執行篇數細項:{data['執行篇數細項']}")
    
    # [15]-[20] 聲量成長分析
    _replace_paragraph_text(
        paras[15],
        f"1. {data['聲量_自品名稱']}在專案後聲量成長數為{data['聲量_自品成長數']}篇,成長率為{data['聲量_自品成長率']}"
    )
    _replace_paragraph_text(paras[16], f"主要聲量集中在{data['聲量_自品集中版面']}")
    _replace_paragraph_text(
        paras[17],
        f"2. {data['聲量_競品A名稱']}在專案後聲量成長數為{data['聲量_競品A成長數']}篇,成長率為{data['聲量_競品A成長率']}"
    )
    _replace_paragraph_text(paras[18], f"主要聲量集中在{data['聲量_競品A集中版面']}")
    _replace_paragraph_text(
        paras[19],
        f"3. {data['聲量_競品B名稱']}在專案後聲量成長數{data['聲量_競品B成長數']}篇,成長率為{data['聲量_競品B成長率']}"
    )
    _replace_paragraph_text(paras[20], f"主要聲量集中在{data['聲量_競品B集中版面']}")
    _replace_paragraph_text(
        paras[21],
        f"4.觀察區間:專案前{data['聲量_觀察區間_前']}、專案後{data['聲量_觀察區間_後']}"
    )
    
    # [23] 自品文字雲 / [24] 分析
    _replace_paragraph_text(paras[23], f"{data['聲量_自品名稱']}文字雲")
    _replace_paragraph_text(paras[24], f"1.分析:{data.get('自品_文字雲_分析', '')}")
    
    # [26] 自品聲量正負評 / [27] 正評摘要標題
    _replace_paragraph_text(paras[26], f"{data['聲量_自品名稱']}聲量正負評")
    
    # [28][29][30] 正評 1-3 → 要動態
    # [32] 負評摘要標題 保留
    # [33][34][35] 負評 1-3 → 要動態
    # [39] 3.分析: 保留
    # [40] 整體以XXXXX
    _fill_review_lines(paras, [28, 29, 30], data.get('自品_正評', []))
    _fill_review_lines(paras, [33, 34, 35], data.get('自品_負評', []))
    _replace_paragraph_text(paras[40], data.get('自品_整體分析', ''))
    
    # [42] 競品文字雲 / [43] 分析
    _replace_paragraph_text(paras[42], f"{data['聲量_競品A名稱']}文字雲")
    _replace_paragraph_text(paras[43], f"分析:{data.get('競品_文字雲_分析', '')}")
    
    # [45] 競品正負評標題
    _replace_paragraph_text(paras[45], f"{data['聲量_競品A名稱']}聲量正負評")
    # [46][47][48] 競品正評
    _fill_review_lines(paras, [46, 47, 48], data.get('競品_正評', []))
    # 競品正評區塊 [46-48] 原範本只有 3 格,但沒有「1.正評摘要」子標題
    # 為跟自品結構一致,我們:
    #   (a) 在 [45]標題 和 [46] 之間插入「1.正評摘要」子標題
    #   (b) 在 [48]最後一格正評 之後插入「空白行、2.負評摘要、負評內容」
    # 用鏈式 insert:每次 insert 後更新 last,確保順序正確
    # 先在 paras[45] 標題後、paras[46] 前,插入「1.正評摘要」子標題
    _insert_paragraph_after(paras[45], "1.正評摘要")
    # 這會把「1.正評摘要」塞在 paras[45] 和 paras[46] 之間

    # 然後在 [48] 之後,鏈式插入:空白行 → 2.負評摘要 → 負評 1,2,...
    負評列表 = data.get('競品_負評', [])
    if 負評列表:
        last = paras[48]
        last = _insert_paragraph_after(last, "")  # 空白分隔
        last = _insert_paragraph_after(last, "2.負評摘要")
        for i, line in enumerate(負評列表, 1):
            last = _insert_paragraph_after(last, f"{i}.{line}")
    _replace_paragraph_text(paras[53], data.get('競品_整體分析', ''))
    
    # [56] 專案回應評價分佈
    _replace_paragraph_text(
        paras[56],
        f"實際溝通量{data['實際溝通量']}篇、保證網友回應數{data['保證網友回應數']}篇、實際回應數{data['實際回應數']}篇"
    )
    
    # [62][63][64] 專案正評摘要 → 動態
    _fill_review_lines(paras, [62, 63, 64], data.get('專案_正評', []))
    # [67][68][69] 專案負評摘要 → 動態
    _fill_review_lines(paras, [67, 68, 69], data.get('專案_負評', []))
    
    # [74][75] 操作觀察 → 動態
    _fill_bullet_lines(paras, [74, 75], data.get('操作觀察', []))
    # [77][78] 未來建議 → 動態
    _fill_bullet_lines(paras, [77, 78], data.get('未來建議', []))
    
    # [80]-[83] Threads 破萬瀏覽(選填)
    if data.get('有_Threads破萬', False):
        _replace_paragraph_text(paras[81], f"-{data['Threads_瀏覽次數']}萬次瀏覽")
        _replace_paragraph_text(paras[82], f"-{data['Threads_愛心']}愛心數")
        _replace_paragraph_text(paras[83], f"-{data['Threads_留言']} 留言數")
    else:
        # 整個 Threads 區塊都移除
        for idx in [80, 81, 82, 83]:
            _replace_paragraph_text(paras[idx], "")
    
    # [85]-[89] Dcard 熱門前 10(選填)
    if data.get('有_Dcard熱門', False):
        _replace_paragraph_text(paras[86], f"-{data['Dcard_板名排名']}")
        _replace_paragraph_text(paras[87], f"-愛心數{data['Dcard_愛心']}")
        _replace_paragraph_text(paras[88], f"- 留言數 {data['Dcard_留言']}")
        _replace_paragraph_text(paras[89], f"-{data['Dcard_曝光']}次曝光")
    else:
        for idx in [85, 86, 87, 88, 89]:
            _replace_paragraph_text(paras[idx], "")
    
    # ===== 表格替換 =====
    # 表 1:KPI
    _fill_kpi_table(tables[0], data.get('KPI', []))
    # 表 2:品牌聲量比較
    _fill_brand_table(tables[1], data)
    # 表 3:網友回應分佈
    _fill_distribution_table(tables[2], data.get('分布表', []))
    
    # ===== 圖片插入(文字雲、截圖)=====
    # 自品文字雲 → [24] 分析段落前
    自品_圖 = data.get('自品_文字雲_bytes')
    if 自品_圖:
        _insert_image_before_paragraph(paras[24], 自品_圖, width_inches=5.0)
    
    # 競品文字雲 → [43] 分析段落前
    競品_圖 = data.get('競品_文字雲_bytes')
    if 競品_圖:
        _insert_image_before_paragraph(paras[43], 競品_圖, width_inches=5.0)
    
    # Threads 截圖
    if data.get('有_Threads破萬', False):
        ts_img = data.get('Threads_截圖_bytes')
        if ts_img:
            _insert_image_before_paragraph(paras[81], ts_img, width_inches=4.0)
    
    # Dcard 截圖
    if data.get('有_Dcard熱門', False):
        dc_img = data.get('Dcard_截圖_bytes')
        if dc_img:
            _insert_image_before_paragraph(paras[86], dc_img, width_inches=4.0)
    
    # 存檔
    out = io.BytesIO()
    doc.save(out)
    return out.getvalue()


def _fill_review_lines(paras, slot_indices, lines):
    """填充正負評摘要
    - slot_indices: 範本原本預留的 3 個段落索引(如 [28, 29, 30])
    - lines: 使用者填的內容(任意行數)
    
    行數 ≤ 3:填前 N 個,其他留空
    行數 > 3:填完 3 個,其餘用 _insert_paragraph_after 新增
    """
    # 清空並填前 len(slot_indices) 行
    for i, idx in enumerate(slot_indices):
        if i < len(lines):
            _replace_paragraph_text(paras[idx], f"{i+1}.{lines[i]}")
        else:
            _replace_paragraph_text(paras[idx], "")
    
    # 若多於 slot 數,在最後一個 slot 後插入
    if len(lines) > len(slot_indices):
        last_para = paras[slot_indices[-1]]
        for i, line in enumerate(lines[len(slot_indices):], len(slot_indices) + 1):
            new_p = _insert_paragraph_after(last_para, f"{i}.{line}")
            last_para = new_p


def _fill_bullet_lines(paras, slot_indices, lines):
    """填充觀察/建議的 bullet 列表(用 - 開頭)"""
    for i, idx in enumerate(slot_indices):
        if i < len(lines):
            _replace_paragraph_text(paras[idx], f"-{lines[i]}")
        else:
            _replace_paragraph_text(paras[idx], "")
    
    if len(lines) > len(slot_indices):
        last_para = paras[slot_indices[-1]]
        for line in lines[len(slot_indices):]:
            new_p = _insert_paragraph_after(last_para, f"-{line}")
            last_para = new_p


def _fill_kpi_table(table, kpi_rows):
    """填 KPI 表(表 1):項目 / 說明 / 實際達成
    範本有 4 列資料(列 0 是表頭),這裡假設 kpi_rows 固定 4 項
    """
    for i, row_data in enumerate(kpi_rows[:4]):
        r = table.rows[i + 1]  # 跳過表頭
        _set_cell_text(r.cells[0], row_data.get('項目', ''))
        _set_cell_text(r.cells[1], row_data.get('說明', ''))
        _set_cell_text(r.cells[2], row_data.get('達成', ''))


def _fill_brand_table(table, data):
    """填品牌聲量表(表 2):品牌 / 專案前 / 專案後
    範本有 3 列資料(自品/競品A/競品B)
    """
    brands = [
        (data.get('聲量_自品名稱', 'AAA自品'),
         data.get('聲量_自品_專案前', ''),
         data.get('聲量_自品_專案後', '')),
        (data.get('聲量_競品A名稱', 'BBB競品'),
         data.get('聲量_競品A_專案前', ''),
         data.get('聲量_競品A_專案後', '')),
        (data.get('聲量_競品B名稱', 'CCC競品'),
         data.get('聲量_競品B_專案前', ''),
         data.get('聲量_競品B_專案後', '')),
    ]
    for i, (name, before, after) in enumerate(brands):
        r = table.rows[i + 1]
        _set_cell_text(r.cells[0], str(name))
        _set_cell_text(r.cells[1], str(before))
        _set_cell_text(r.cells[2], str(after))


def _fill_distribution_table(table, rows):
    """填網友回應分佈表(表 3)
    範本 4 列資料(含總計),欄位:溝通分布/實際溝通/正面/負面/議題/產品/複合/小計
    rows 列數可能不同,動態處理

    關鍵:要複製範本資料列的 XML 來新增列(保留邊框、背景色、字型等所有樣式),
    不能用 table.add_row(),否則新列沒邊框。
    """
    from docx.table import _Row

    fields = ['版面', '實際溝通', '正面', '負面', '議題', '產品', '複合', '小計']

    # 範本原結構:row 0=表頭, row 1-2=一般資料列樣板, row 3=總計列樣板(可能有不同樣式)
    # 保留 row 1 的 XML 當「一般資料列樣板」
    # 保留最後一列的 XML 當「總計列樣板」
    if len(table.rows) < 2:
        # 範本結構異常,直接 add_row(有邊框問題但不會壞)
        for row_data in rows:
            new_row = table.add_row()
            for ci, field in enumerate(fields):
                if ci < len(new_row.cells):
                    _set_cell_text(new_row.cells[ci], str(row_data.get(field, '')))
        return

    # 複製樣板 XML(在刪除前先存)
    template_tr_normal = deepcopy(table.rows[1]._tr)
    template_tr_total = deepcopy(table.rows[-1]._tr) if len(table.rows) >= 3 else deepcopy(table.rows[1]._tr)

    # 刪除所有非表頭的列(從後往前刪,避免 index 錯亂)
    for r in list(table.rows[1:]):
        r._tr.getparent().remove(r._tr)

    # 用樣板新增列
    # 判斷哪些是「總計列」(名稱為「總計」或「合計」):用總計樣板,其他用一般樣板
    for row_data in rows:
        is_total = str(row_data.get('版面', '')).strip() in ('總計', '合計')
        template_tr = template_tr_total if is_total else template_tr_normal

        new_tr = deepcopy(template_tr)
        table._tbl.append(new_tr)

        # 包裝成 _Row 物件以便存取 cells
        new_row = _Row(new_tr, table)

        for ci, field in enumerate(fields):
            if ci < len(new_row.cells):
                _set_cell_text(new_row.cells[ci], str(row_data.get(field, '')))


def _insert_image_before_paragraph(paragraph, img_bytes: bytes, width_inches: float = 5.0):
    """在指定段落「前」插入一張圖片"""
    # 在原段落前新增一個空段落,然後把圖片塞進該新段落
    new_p = OxmlElement('w:p')
    paragraph._p.addprevious(new_p)
    from docx.text.paragraph import Paragraph
    new_para = Paragraph(new_p, paragraph._parent)
    run = new_para.add_run()
    try:
        run.add_picture(io.BytesIO(img_bytes), width=Inches(width_inches))
    except Exception as e:
        # 若圖片格式不支援,塞一行說明
        new_para.add_run(f"[圖片載入失敗:{e}]")



# ==================== Streamlit 表單 UI ====================

def render_word_form(pdf_defaults: dict) -> Optional[dict]:
    """渲染 Word 補填表單
    
    pdf_defaults 由主程式從 PDF 自動抓取傳入,用於填預設值:
    {
        '執行篇數細項': "...",         # PDF 自動產
        '預計執行篇數': 89,
        '實際執行篇數': 89,
        '達成率': "100%",
        'KPI': [...],                   # 4 項
        '實際溝通量': 89,
        '保證網友回應數': 52,
        '實際回應數': 413,
        '分布表': [...],
    }
    
    回傳使用者填好的完整 data dict,或 None(未按下送出)
    """
    import streamlit as st
    
    with st.form("word_report_form"):
        st.markdown("### 📝 補填 Word 報告需要的欄位")
        st.caption("💡 PDF 已自動帶出的部分不會顯示,只需補其他欄位。所有欄位都可修改。")
        
        # ===== 區塊 1:基本資訊 =====
        with st.expander("① 基本資訊", expanded=True):
            # 專案名稱 + 視覺風格(用於「結案指令詞」匯出)
            n1, n2 = st.columns(2)
            with n1:
                專案名稱 = st.text_input(
                    "專案名稱(用於 Word 封面 + 結案指令詞)",
                    value="",
                    placeholder="例:friDay 影音稻草人 2026 口碑行銷",
                )
            with n2:
                視覺風格 = st.text_input(
                    "視覺風格提示詞(僅用於結案指令詞)",
                    value="",
                    placeholder="例:科技感 + 深藍紫色系 + 幾何線條",
                )

            c1, c2, c3 = st.columns(3)
            with c1:
                走期_start = st.date_input("操作開始日期", value=date.today() - timedelta(days=60))
            with c2:
                走期_end = st.date_input("操作結束日期", value=date.today())
            with c3:
                work_days = st.number_input("工作天數", min_value=1, value=50, step=1)

            目的_text = st.text_area(
                "操作目的(一行一點,開頭請用 a. b. c.)",
                value="a.XXXXX\nb.XXXXX",
                height=100,
            )
        
        # ===== 區塊 2:品牌聲量比較 =====
        with st.expander("② 網路聲量比較(自品 + 競品 A/B)", expanded=False):
            cp1, cp2 = st.columns(2)
            with cp1:
                觀察_前 = st.text_input("觀察區間 - 專案前", value="2026/3/1~2026/5/31")
            with cp2:
                觀察_後 = st.text_input("觀察區間 - 專案後", value="2026/6/1~2026/8/10")
            
            st.markdown("**自品**")
            a1, a2, a3 = st.columns(3)
            with a1: 自品_name = st.text_input("自品名稱", value="AAA自品", key="自品_name")
            with a2: 自品_before = st.text_input("專案前聲量", value="80 篇", key="自品_before")
            with a3: 自品_after = st.text_input("專案後聲量", value="105 篇", key="自品_after")
            b1, b2 = st.columns(2)
            with b1: 自品_grow_num = st.number_input("成長數(篇)", min_value=0, value=25, key="自品_grow_num")
            with b2: 自品_grow_pct = st.text_input("成長率", value="25.00%", key="自品_grow_pct")
            自品_platforms = st.text_input("主要聲量集中版面", value="Threads、Dcard", key="自品_platforms")
            
            st.markdown("**競品 A**")
            ba1, ba2, ba3 = st.columns(3)
            with ba1: cA_name = st.text_input("競品 A 名稱", value="BBB競品", key="cA_name")
            with ba2: cA_before = st.text_input("專案前聲量", value="40 篇", key="cA_before")
            with ba3: cA_after = st.text_input("專案後聲量", value="50 篇", key="cA_after")
            ba4, ba5 = st.columns(2)
            with ba4: cA_grow_num = st.number_input("成長數", min_value=0, value=10, key="cA_grow_num")
            with ba5: cA_grow_pct = st.text_input("成長率", value="12.50%", key="cA_grow_pct")
            cA_platforms = st.text_input("主要聲量集中版面", value="Threads", key="cA_platforms")
            
            st.markdown("**競品 B**")
            bb1, bb2, bb3 = st.columns(3)
            with bb1: cB_name = st.text_input("競品 B 名稱", value="CCC競品", key="cB_name")
            with bb2: cB_before = st.text_input("專案前聲量", value="60 篇", key="cB_before")
            with bb3: cB_after = st.text_input("專案後聲量", value="65 篇", key="cB_after")
            bb4, bb5 = st.columns(2)
            with bb4: cB_grow_num = st.number_input("成長數", min_value=0, value=5, key="cB_grow_num")
            with bb5: cB_grow_pct = st.text_input("成長率", value="8.00%", key="cB_grow_pct")
            cB_platforms = st.text_input("主要聲量集中版面", value="Threads", key="cB_platforms")
        
        # ===== 區塊 3:自品文字雲 + 正負評 =====
        with st.expander("③ 自品 — 文字雲 + 正負評", expanded=False):
            自品_cloud_img = st.file_uploader(
                "上傳自品文字雲圖片(選填)",
                type=["png", "jpg", "jpeg"],
                key="自品_cloud",
            )
            自品_cloud_text = st.text_area("自品文字雲分析", value="本區間XXXXXX", key="自品_cloud_text", height=80)
            自品_pos_text = st.text_area(
                "自品正評摘要(一行一則,行數不限)",
                value="",
                key="自品_pos",
                height=120,
                placeholder="做完明顯緊緻\n醫師技術純熟\n...",
            )
            自品_neg_text = st.text_area(
                "自品負評摘要(一行一則,行數不限)",
                value="",
                key="自品_neg",
                height=120,
            )
            自品_overall = st.text_area("自品整體分析", value="整體以XXXXX", key="自品_overall", height=80)
        
        # ===== 區塊 4:競品文字雲 + 正負評 =====
        with st.expander("④ 競品 A — 文字雲 + 正負評", expanded=False):
            競品_cloud_img = st.file_uploader(
                "上傳競品文字雲圖片(選填)",
                type=["png", "jpg", "jpeg"],
                key="競品_cloud",
            )
            競品_cloud_text = st.text_area("競品文字雲分析", value="", key="競品_cloud_text", height=80)
            競品_pos_text = st.text_area("競品正評摘要(一行一則)", value="", key="競品_pos", height=120)
            競品_neg_text = st.text_area("競品負評摘要(一行一則)", value="", key="競品_neg", height=120)
            競品_overall = st.text_area("競品整體分析", value="整體以XXXXX", key="競品_overall", height=80)
        
        # ===== 區塊 5:專案正負評 =====
        with st.expander("⑤ 專案回應正負評摘要", expanded=False):
            專案_pos = st.text_area(
                "正評摘要(一行一則,行數不限)",
                value="", key="專案_pos", height=120,
            )
            專案_neg = st.text_area(
                "負評摘要(一行一則,行數不限)",
                value="", key="專案_neg", height=120,
            )
        
        # ===== 區塊 6:操作觀察與未來建議 =====
        with st.expander("⑥ 操作觀察與未來建議", expanded=False):
            觀察 = st.text_area("操作觀察(一行一點)", value="", key="觀察", height=100)
            建議 = st.text_area("未來操作建議(一行一點)", value="", key="建議", height=100)
        
        # ===== 區塊 7:平台熱門效益(選填)=====
        with st.expander("⑦ 平台熱門效益(選填)", expanded=False):
            st.markdown("**Threads 破萬瀏覽**")
            有_threads = st.checkbox("本次有 Threads 破萬瀏覽", value=False, key="有_threads")
            t_img = st.file_uploader(
                "上傳 Threads 截圖(選填)",
                type=["png", "jpg", "jpeg"],
                key="t_img",
            )
            tt1, tt2, tt3 = st.columns(3)
            with tt1: t_views = st.number_input("瀏覽次數(萬)", min_value=0.0, value=0.0, step=0.1, key="t_views")
            with tt2: t_likes = st.number_input("愛心數", min_value=0, value=0, key="t_likes")
            with tt3: t_comments = st.number_input("留言數", min_value=0, value=0, key="t_comments")
            
            st.markdown("---")
            st.markdown("**Dcard 熱門前 10**")
            有_dcard = st.checkbox("本次有 Dcard 熱門前 10", value=False, key="有_dcard")
            d_img = st.file_uploader(
                "上傳 Dcard 截圖(選填)",
                type=["png", "jpg", "jpeg"],
                key="d_img",
            )
            d_rank = st.text_input("板名 + 熱門排名", value="美妝版熱門前 5", key="d_rank")
            dd1, dd2, dd3 = st.columns(3)
            with dd1: d_likes = st.number_input("愛心數", min_value=0, value=0, key="d_likes")
            with dd2: d_comments = st.number_input("留言數", min_value=0, value=0, key="d_comments")
            with dd3: d_views = st.text_input("曝光", value="5 萬", key="d_views")
        
        submitted = st.form_submit_button("📄 生成 Word 報告", use_container_width=True, type="primary")
    
    if not submitted:
        return None
    
    # ===== 組裝 data dict =====
    def split_lines(text: str) -> list:
        return [l.strip() for l in (text or "").split("\n") if l.strip()]
    
    def read_img(uploaded) -> Optional[bytes]:
        return uploaded.read() if uploaded is not None else None
    
    data = {
        # 基本(含專案名/視覺風格,用於結案指令詞)
        "專案名稱": 專案名稱,
        "視覺風格": 視覺風格,
        "操作走期_開始": 走期_start.strftime("%Y/%m/%d"),
        "操作走期_結束": 走期_end.strftime("%Y/%m/%d"),
        "工作天數": int(work_days),
        "操作目的_行": split_lines(目的_text),
        
        # 從 PDF 帶
        "執行篇數細項": pdf_defaults.get('執行篇數細項', ''),
        "預計執行篇數": pdf_defaults.get('預計執行篇數', 0),
        "實際執行篇數": pdf_defaults.get('實際執行篇數', 0),
        "達成率": pdf_defaults.get('達成率', '100%'),
        "KPI": pdf_defaults.get('KPI', []),
        "實際溝通量": pdf_defaults.get('實際溝通量', 0),
        "保證網友回應數": pdf_defaults.get('保證網友回應數', 0),
        "實際回應數": pdf_defaults.get('實際回應數', 0),
        "分布表": pdf_defaults.get('分布表', []),
        
        # 聲量
        "聲量_觀察區間_前": 觀察_前, "聲量_觀察區間_後": 觀察_後,
        "聲量_自品名稱": 自品_name, "聲量_自品_專案前": 自品_before, "聲量_自品_專案後": 自品_after,
        "聲量_自品成長數": int(自品_grow_num), "聲量_自品成長率": 自品_grow_pct,
        "聲量_自品集中版面": 自品_platforms,
        "聲量_競品A名稱": cA_name, "聲量_競品A_專案前": cA_before, "聲量_競品A_專案後": cA_after,
        "聲量_競品A成長數": int(cA_grow_num), "聲量_競品A成長率": cA_grow_pct,
        "聲量_競品A集中版面": cA_platforms,
        "聲量_競品B名稱": cB_name, "聲量_競品B_專案前": cB_before, "聲量_競品B_專案後": cB_after,
        "聲量_競品B成長數": int(cB_grow_num), "聲量_競品B成長率": cB_grow_pct,
        "聲量_競品B集中版面": cB_platforms,
        
        # 自品
        "自品_文字雲_bytes": read_img(自品_cloud_img),
        "自品_文字雲_分析": 自品_cloud_text,
        "自品_正評": split_lines(自品_pos_text),
        "自品_負評": split_lines(自品_neg_text),
        "自品_整體分析": 自品_overall,
        
        # 競品
        "競品_文字雲_bytes": read_img(競品_cloud_img),
        "競品_文字雲_分析": 競品_cloud_text,
        "競品_正評": split_lines(競品_pos_text),
        "競品_負評": split_lines(競品_neg_text),
        "競品_整體分析": 競品_overall,
        
        # 專案正負評
        "專案_正評": split_lines(專案_pos),
        "專案_負評": split_lines(專案_neg),
        
        # 觀察與建議
        "操作觀察": split_lines(觀察),
        "未來建議": split_lines(建議),
        
        # 平台熱門(選填)
        "有_Threads破萬": bool(有_threads),
        "Threads_瀏覽次數": float(t_views),
        "Threads_愛心": int(t_likes),
        "Threads_留言": int(t_comments),
        "Threads_截圖_bytes": read_img(t_img),
        
        "有_Dcard熱門": bool(有_dcard),
        "Dcard_板名排名": d_rank,
        "Dcard_愛心": int(d_likes),
        "Dcard_留言": int(d_comments),
        "Dcard_曝光": d_views,
        "Dcard_截圖_bytes": read_img(d_img),
    }
    return data


# ==================== 結案指令詞(簡報 prompt)===============

PROMPT_TEMPLATE_B64 = ""


def _get_prompt_template() -> str:
    """取得結案指令詞範本的純文字"""
    return base64.b64decode(PROMPT_TEMPLATE_B64).decode('utf-8')


def build_prompt_text(data: dict) -> str:
    """生成「結案指令詞」文字(給 Gamma / Claude 做簡報用)
    
    替換範本中的 ●XXX● 標記:
    - ●(貼入選擇的視覺風格提示詞)● → 使用者填的視覺風格
    - ●XXXXXX專案名稱XXXX● → 專案名稱
    - ●AA自品 VS. BB競品 VS.CC競品● → {自品} VS. {競品A} VS. {競品B}
    - ●自品AA● → 自品名稱
    - ●AAA自品● → 自品名稱(多處)
    """
    text = _get_prompt_template()
    
    專案名 = data.get('專案名稱', '') or '(未填專案名稱)'
    視覺 = data.get('視覺風格', '') or '(未填視覺風格)'
    自品 = data.get('聲量_自品名稱', 'AAA自品') or 'AAA自品'
    競A = data.get('聲量_競品A名稱', 'BBB競品') or 'BBB競品'
    競B = data.get('聲量_競品B名稱', 'CCC競品') or 'CCC競品'
    
    text = text.replace('●(貼入選擇的視覺風格提示詞)●', 視覺)
    text = text.replace('●XXXXXX專案名稱XXXX●', 專案名)
    text = text.replace('●AA自品 VS. BB競品 VS.CC競品●', f'{自品} VS. {競A} VS. {競B}')
    text = text.replace('●自品AA●', 自品)
    text = text.replace('●AAA自品●', 自品)
    
    return text
